function futureNominal(amount, rate, years){ return amount*Math.pow(1+rate, years); }
function realValue(amount, rate, years){ return amount/Math.pow(1+rate, years); }
function lossPct(rate, years){ return (1 - 1/Math.pow(1+rate, years))*100; }
function realRate(nominalRate, inflation){ return (1+nominalRate)/(1+inflation)-1; }
var EXPORTS={futureNominal:futureNominal, realValue:realValue, lossPct:lossPct, realRate:realRate};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.InflationForgePure = EXPORTS; }
